/* polymorphic. */
static void convert_XrHapticBaseHeader_win32_to_host(struct conversion_context *ctx, const XrHapticBaseHeader32 *in, XrHapticBaseHeader *out)
{
    if (!in) return;

    switch (in->type)
    {
    case XR_TYPE_HAPTIC_AMPLITUDE_ENVELOPE_VIBRATION_FB: convert_XrHapticAmplitudeEnvelopeVibrationFB_win32_to_host((const void *)in, (void *)out); break;
    case XR_TYPE_HAPTIC_PARAMETRIC_VIBRATION_EXT: convert_XrHapticParametricVibrationEXT_win32_to_host(ctx, (const void *)in, (void *)out); break;
    case XR_TYPE_HAPTIC_PCM_VIBRATION_FB: convert_XrHapticPcmVibrationFB_win32_to_host((const void *)in, (void *)out); break;
    case XR_TYPE_HAPTIC_VIBRATION: convert_XrHapticVibration_win32_to_host((const void *)in, (void *)out); break;
    default:
        TRACE("Unhandled type %u.\n", in->type);
        out->type = in->type;
        out->next = NULL;
        break;
    }
    if (in->next)
        FIXME("Unexpected next\n");
}

