    case XR_TYPE_COMPOSITION_LAYER_CYLINDER_KHR: convert_XrCompositionLayerCylinderKHR_win32_to_host((const void *)in, (void *)out); break;
    case XR_TYPE_COMPOSITION_LAYER_EQUIRECT2_KHR: convert_XrCompositionLayerEquirect2KHR_win32_to_host((const void *)in, (void *)out); break;
    case XR_TYPE_COMPOSITION_LAYER_EQUIRECT_KHR: convert_XrCompositionLayerEquirectKHR_win32_to_host((const void *)in, (void *)out); break;
